// Разворачиваем один набор параметров в два запроса: по одному на тег.
// Так следующий узел отработает дважды, и не нужен Merge.
const p = $input.first().json;
return [
  { json: { role: 'from', tag: p.tagFrom, owner: p.owner, repo: p.repo, tagFrom: p.tagFrom, tagTo: p.tagTo } },
  { json: { role: 'to',   tag: p.tagTo,   owner: p.owner, repo: p.repo, tagFrom: p.tagFrom, tagTo: p.tagTo } }
];

// Склеиваем два ответа в одно окно релиза.
// since сдвинут на секунду вперёд: сам коммит базового тега
// в релиз не входит, он был выкачен в прошлый раз.
const items = $input.all();
const params = $('Развернуть в два запроса').first().json;

const byRole = {};
for (let i = 0; i < items.length; i++) {
  const role = $('Развернуть в два запроса').all()[i].json.role;
  byRole[role] = items[i].json;
}

if (!byRole.from || !byRole.to) {
  throw new Error('не удалось разрешить оба тега');
}

const fromDate = new Date(byRole.from.commit.committer.date);
const since = new Date(fromDate.getTime() + 1000).toISOString();
const until = byRole.to.commit.committer.date;

return [{ json: {
  owner: params.owner,
  repo: params.repo,
  tagFrom: params.tagFrom,
  tagTo: params.tagTo,
  shaFrom: byRole.from.sha,
  shaTo: byRole.to.sha,
  since,
  until,
  branch: 'kvart-demo',
  issueTitle: `Релиз ${params.tagTo}: чек-лист выкатки`,
  reportPath: `/workspace/reports/release-${params.tagTo}.md`,
  checklistPath: '/workspace/release/checklist.md',
  templatePath: '/workspace/release/notes-template.md'
}}];
